interface OrderItem {
  name: string;
  price: number;
  quantity: number;
}

function formatInvoice(items: OrderItem[]): {
  lines: string[];
  total: number;
} {
  const lines = items.map(
    (item) => `${item.name} x${item.quantity} - $${(item.price * item.quantity).toFixed(2)}`
  );
  const total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  return { lines, total: Number(total.toFixed(2)) };
}

// Jest tests
describe('formatInvoice', () => {
  test('should match snapshot for a typical invoice', () => {
    const result = formatInvoice([
      { name: 'Widget', price: 9.99, quantity: 2 },
      { name: 'Gadget', price: 4.5, quantity: 1 },
    ]);

    // A failing snapshot here means the OUTPUT SHAPE changed. Update it
    // (`jest --updateSnapshot`) only after confirming the new shape is
    // an intentional change, not a bug in formatInvoice's logic.
    expect(result).toMatchSnapshot();

    // Snapshot alone would not catch a wrong total that happens to still
    // look plausible - pair it with an explicit assertion on the value
    // that matters most.
    expect(result.total).toBe(24.48);
  });

  test('should match snapshot for an empty invoice', () => {
    const result = formatInvoice([]);

    expect(result).toMatchSnapshot();
  });
});

description.en:
Write unit tests for a `getActiveUserNames` function that filters and transforms a list of users. Use Jest's structural matchers (`toEqual`, `toContain`, `toHaveLength`, `toMatchObject`) instead of manually checking individual array indices.

**Requirements:**

- Use `toHaveLength()` to check the size of the returned array
- Use `toContain()` to check that a specific name is present, without asserting full array order
- Use `toEqual()` to compare a full array/object for deep equality
- Use `toMatchObject()` to check that an object contains a subset of expected properties, ignoring extra fields
- Demonstrate why `toBe()` would be the wrong matcher here
- Cover at least 4 test cases

**Function signature:**

```typescript
interface User {
  id: string;
  name: string;
  active: boolean;
  lastLogin: string;
}

function getActiveUserNames(users: User[]): string[] {
  return users.filter((u) => u.active).map((u) => u.name);
}
```

**Example inputs/outputs:**

- Input with 3 users (2 active) → getActiveUserNames(...) → array of 2 names
- Input with no active users → []

**Edge cases:**

- Empty input array
- All users inactive
- Array order in the result should follow input order, not be assumed by the test to always be alphabetical

