solution:
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { UserProfile } from './UserProfile';
import { fetchUser, updateUser } from './api';

jest.mock('./api');

const mockedFetchUser = fetchUser as jest.MockedFunction<typeof fetchUser>;
const mockedUpdateUser = updateUser as jest.MockedFunction<typeof updateUser>;

const user = { id: '1', name: 'Ada Lovelace', email: 'ada@example.com' };

describe('UserProfile', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  test('shows loading state, then renders the user', async () => {
    mockedFetchUser.mockResolvedValue(user);

    render(<UserProfile userId="1" />);

    expect(screen.getByText('Loading...')).toBeInTheDocument();

    expect(await screen.findByText('Ada Lovelace')).toBeInTheDocument();
    expect(screen.getByText('ada@example.com')).toBeInTheDocument();
    expect(screen.queryByText('Loading...')).not.toBeInTheDocument();
  });

  test('shows an error message when fetchUser rejects', async () => {
    mockedFetchUser.mockRejectedValue(new Error('network down'));

    render(<UserProfile userId="1" />);

    expect(await screen.findByText('Failed to load user')).toBeInTheDocument();
  });

  test('lets the user edit and save their name', async () => {
    mockedFetchUser.mockResolvedValue(user);
    mockedUpdateUser.mockResolvedValue({ ...user, name: 'Ada Byron' });
    const typist = userEvent.setup();

    render(<UserProfile userId="1" />);
    await screen.findByText('Ada Lovelace');

    await typist.click(screen.getByRole('button', { name: /edit/i }));

    const input = screen.getByRole('textbox', { name: /name/i });
    await typist.clear(input);
    await typist.type(input, 'Ada Byron');
    await typist.click(screen.getByRole('button', { name: /save/i }));

    await waitFor(() => {
      expect(mockedUpdateUser).toHaveBeenCalledWith('1', { name: 'Ada Byron' });
    });
    expect(await screen.findByText('Ada Byron')).toBeInTheDocument();
  });

  test('shows an inline error when updateUser rejects and keeps the form open', async () => {
    mockedFetchUser.mockResolvedValue(user);
    mockedUpdateUser.mockRejectedValue(new Error('save failed'));
    const typist = userEvent.setup();

    render(<UserProfile userId="1" />);
    await screen.findByText('Ada Lovelace');

    await typist.click(screen.getByRole('button', { name: /edit/i }));
    await typist.click(screen.getByRole('button', { name: /save/i }));

    expect(await screen.findByText(/could not save/i)).toBeInTheDocument();
    expect(screen.getByRole('textbox', { name: /name/i })).toBeInTheDocument();
  });
});

description.en:
You have a custom hook `useUserForm` that manages a form's values, validation errors, dirty state, and an async submit flow.

**Requirements:**

- Use `renderHook` from `@testing-library/react` (not the deprecated `@testing-library/react-hooks`)
- Wrap every state-changing call in `act()`
- Test field updates, validation errors, dirty-state tracking, `reset()`, and both a successful and a failing async submission
- Assert on `result.current` after each `act()`, not before

**Hook signature:**

```typescript
interface FormValues {
  name: string;
  email: string;
}

interface FormState {
  values: FormValues;
  errors: Partial<Record<keyof FormValues, string>>;
  isDirty: boolean;
  isSubmitting: boolean;
}

interface UseUserFormOptions {
  initialValues: FormValues;
  validate: (values: FormValues) => Partial<Record<keyof FormValues, string>>;
  onSubmit: (values: FormValues) => Promise<void>;
}

interface UseUserFormResult extends FormState {
  setField: (field: keyof FormValues, value: string) => void;
  reset: () => void;
  submit: () => Promise<void>;
}

declare function useUserForm(options: UseUserFormOptions): UseUserFormResult;
```

**Example behavior:**

- `setField('name', 'Ada')` updates `values.name`, sets `isDirty` to `true`, re-runs `validate` and updates `errors`
- `reset()` restores `initialValues`, clears `errors`, sets `isDirty` back to `false`
- `submit()` sets `isSubmitting` to `true`, calls `onSubmit(values)`, and sets `isSubmitting` back to `false` whether it resolves or rejects

**Edge cases:**

- Calling `submit()` while `errors` is non-empty should not call `onSubmit` at all
- `onSubmit` rejecting must not leave `isSubmitting` stuck at `true`
- Calling `setField` with the same value it already has should not falsely reset `isDirty` to `false`

