  onSubmit: (values: FormValues) => Promise<void>;
}

interface UseUserFormResult extends FormState {
  setField: (field: keyof FormValues, value: string) => void;
  reset: () => void;
  submit: () => Promise<void>;
}

declare function useUserForm(options: UseUserFormOptions): UseUserFormResult;
```

**Пример поведения:**

- `setField('name', 'Ada')` обновляет `values.name`, ставит `isDirty` в `true`, заново прогоняет `validate` и обновляет `errors`
- `reset()` восстанавливает `initialValues`, очищает `errors`, возвращает `isDirty` в `false`
- `submit()` ставит `isSubmitting` в `true`, вызывает `onSubmit(values)` и возвращает `isSubmitting` в `false` независимо от того, зарезолвился промис или отклонился

**Граничные случаи:**

- Вызов `submit()` при непустых `errors` не должен вызывать `onSubmit` вообще
- Reject у `onSubmit` не должен оставлять `isSubmitting` навсегда `true`
- Вызов `setField` с тем же значением, что уже есть, не должен ошибочно сбрасывать `isDirty` в `false`

