import { renderHook, act } from '@testing-library/react';
import { useUserForm } from './useUserForm';

const initialValues = { name: '', email: '' };

function noErrors() {
  return {};
}

function requireName(values: { name: string; email: string }) {
  return values.name.trim() ? {} : { name: 'Name is required' };
}

describe('useUserForm', () => {
  test('setField updates values and marks the form dirty', () => {
    const { result } = renderHook(() =>
      useUserForm({ initialValues, validate: noErrors, onSubmit: jest.fn() })
    );

    act(() => {
      result.current.setField('name', 'Ada');
    });

    expect(result.current.values.name).toBe('Ada');
    expect(result.current.isDirty).toBe(true);
  });

  test('validate is re-run on every field change and populates errors', () => {
    const { result } = renderHook(() =>
      useUserForm({ initialValues, validate: requireName, onSubmit: jest.fn() })
    );

    act(() => {
      result.current.setField('name', '');
    });
    expect(result.current.errors.name).toBe('Name is required');

    act(() => {
      result.current.setField('name', 'Grace');
    });
    expect(result.current.errors.name).toBeUndefined();
  });

  test('reset restores initialValues, clears errors and isDirty', () => {
    const { result } = renderHook(() =>
      useUserForm({ initialValues, validate: requireName, onSubmit: jest.fn() })
    );

    act(() => {
      result.current.setField('name', 'Grace');
    });
    act(() => {
      result.current.reset();
    });

    expect(result.current.values).toEqual(initialValues);
    expect(result.current.errors).toEqual({});
    expect(result.current.isDirty).toBe(false);
  });

  test('submit calls onSubmit only when there are no errors, and toggles isSubmitting', async () => {
    const onSubmit = jest.fn().mockResolvedValue(undefined);
    const { result } = renderHook(() =>
      useUserForm({ initialValues, validate: requireName, onSubmit })
    );

    await act(async () => {
      await result.current.submit();
    });
    expect(onSubmit).not.toHaveBeenCalled();

    act(() => {
      result.current.setField('name', 'Grace');
    });

    await act(async () => {
      await result.current.submit();
    });
    expect(onSubmit).toHaveBeenCalledWith({ name: 'Grace', email: '' });
    expect(result.current.isSubmitting).toBe(false);
  });

  test('submit resets isSubmitting to false even when onSubmit rejects', async () => {
    const onSubmit = jest.fn().mockRejectedValue(new Error('server error'));
    const { result } = renderHook(() =>
      useUserForm({ initialValues: { name: 'Grace', email: '' }, validate: noErrors, onSubmit })
    );

    await act(async () => {
      await result.current.submit().catch(() => {});
    });

    expect(result.current.isSubmitting).toBe(false);
  });
});

