solution:
interface ContractInteraction {
  description: string;
  request: { method: string; path: string };
  response: { status: number; body: Record<string, unknown> };
}

function defineConsumerContract(): ContractInteraction {
  return {
    description: 'a request for user with id 1',
    request: { method: 'GET', path: '/users/1' },
    response: {
      status: 200,
      body: { id: 'string', name: 'string', email: 'string', createdAt: 'string' },
    },
  };
}

type ShapeMismatch = string;

function compareShape(
  expected: Record<string, unknown>,
  actual: unknown,
  path = ''
): ShapeMismatch[] {
  const mismatches: ShapeMismatch[] = [];

  if (actual === null || typeof actual !== 'object') {
    mismatches.push(`${path || 'root'}: expected object, got ${typeof actual}`);
    return mismatches;
  }

  const actualObj = actual as Record<string, unknown>;

  for (const [key, expectedType] of Object.entries(expected)) {
    const fieldPath = path ? `${path}.${key}` : key;

    if (!(key in actualObj)) {
      mismatches.push(`missing field: ${fieldPath}`);
      continue;
    }

    const actualValue = actualObj[key];

    if (typeof expectedType === 'object' && expectedType !== null) {
      // nested shape descriptor
      mismatches.push(
        ...compareShape(expectedType as Record<string, unknown>, actualValue, fieldPath)
      );
    } else {
      const expectedTypeName = expectedType as string;
      const actualTypeName = typeof actualValue;
      if (actualTypeName !== expectedTypeName) {
        mismatches.push(
          `type mismatch at ${fieldPath}: expected ${expectedTypeName}, got ${actualTypeName}`
        );
      }
    }
  }

  return mismatches;
}

async function verifyProvider(
  contract: ContractInteraction,
  providerHandler: (req: { method: string; path: string }) => Promise<{ status: number; body: unknown }>
): Promise<{ passed: boolean; mismatches: string[] }> {
  try {
    const actualResponse = await providerHandler(contract.request);

    const mismatches: string[] = [];

    if (actualResponse.status !== contract.response.status) {
      mismatches.push(
        `status mismatch: expected ${contract.response.status}, got ${actualResponse.status}`
      );
    }

    if (actualResponse.body === undefined || actualResponse.body === null) {
      mismatches.push('response body is missing entirely');
      return { passed: false, mismatches };
    }

    mismatches.push(...compareShape(contract.response.body, actualResponse.body));

    return { passed: mismatches.length === 0, mismatches };
  } catch (err) {
    return { passed: false, mismatches: [`provider handler threw: ${(err as Error).message}`] };
  }
}

describe('consumer-driven contract: GET /users/:id', () => {
  test('provider satisfies consumer contract', async () => {
    const contract = defineConsumerContract();
    const provider = async () => ({
      status: 200,
      body: { id: '1', name: 'Ann', email: 'ann@x.com', createdAt: '2024-01-01', extra: 'ignored' },
    });

    const result = await verifyProvider(contract, provider);
    expect(result.passed).toBe(true);
    expect(result.mismatches).toHaveLength(0);
  });

  test('fails when provider is missing a field', async () => {
    const contract = defineConsumerContract();
    const provider = async () => ({
      status: 200,
      body: { id: '1', name: 'Ann', createdAt: '2024-01-01' },
    });

    const result = await verifyProvider(contract, provider);
    expect(result.passed).toBe(false);
    expect(result.mismatches).toContain('missing field: email');
  });
});

description.en:
You have a `NotificationClient` class that wraps a WebSocket connection: it connects, receives JSON-encoded events (`{ type: 'notification', payload: {...} }` or `{ type: 'heartbeat' }`), reconnects with exponential backoff on disconnect, and exposes an `onNotification(callback)` subscription API. Write tests for it WITHOUT a real network connection, using a fake WebSocket implementation you control.

**Requirements:**

- Build a `FakeWebSocket` test double that mimics the browser `WebSocket` API surface used by the client (`onopen`, `onmessage`, `onclose`, `onerror`, `send`, `close`) and lets the test manually trigger these events
- Test that `onNotification` callbacks fire only for `type: 'notification'` messages, not for heartbeats
- Test that multiple subscribers registered via `onNotification` all get called for the same event, and that unsubscribing stops further calls
- Test the reconnect-with-backoff behavior: simulate a disconnect (`onclose` fires), assert the client attempts to reconnect after a delay, and that repeated disconnects increase the delay (exponential backoff), using fake timers so the test doesn't actually wait in real time
- Test that out-of-order or malformed JSON messages don't crash the client or double-fire callbacks

**Function signature:**

```typescript
interface NotificationEvent {
  type: 'notification';
  payload: { id: string; message: string };
}

class NotificationClient {
  constructor(url: string, wsFactory: (url: string) => WebSocket);
  onNotification(callback: (event: NotificationEvent) => void): () => void; // returns unsubscribe fn
  connect(): void;
  disconnect(): void;
}
```

**Example:**

- Fake socket fires `onmessage` with `{ type: 'notification', payload: { id: '1', message: 'hi' } }` → registered callback receives that payload
- Fake socket fires `onclose` → after backoff delay, `wsFactory` is called again to reconnect

**Edge cases:**

- `onmessage` fires with invalid JSON string → client should not throw, should not call any notification callback
- `onclose` fires while a reconnect attempt is already pending → should not stack multiple simultaneous reconnect timers
- Unsubscribe called twice by the same subscriber → should not throw

