solution:
interface Mutant {
  mutatedSource: string;
  description: string;
}

interface TestCase {
  input: unknown[];
  expectedOutput: unknown;
}

// Ordered longest-first so we don't accidentally match '>' inside '>=' etc.
const OPERATOR_MUTATIONS: [string, string][] = [
  ['>=', '>'],
  ['<=', '<'],
  ['===', '!=='],
  ['!==', '==='],
  ['&&', '||'],
  ['||', '&&'],
  ['>', '>='],
  ['<', '<='],
  ['+', '-'],
  ['-', '+'],
];

function findOperatorOccurrences(source: string, operator: string): number[] {
  const positions: number[] = [];
  let idx = source.indexOf(operator);
  while (idx !== -1) {
    positions.push(idx);
    idx = source.indexOf(operator, idx + operator.length);
  }
  return positions;
}

function isPositionAlreadyConsumed(pos: number, len: number, consumed: [number, number][]): boolean {
  return consumed.some(([start, end]) => pos < end && pos + len > start);
}

function generateMutants(source: string): Mutant[] {
  const mutants: Mutant[] = [];
  const consumedRanges: [number, number][] = []; // tracks operator spans already matched by a longer operator

  for (const [from, to] of OPERATOR_MUTATIONS) {
    const positions = findOperatorOccurrences(source, from);
    for (const pos of positions) {
      if (isPositionAlreadyConsumed(pos, from.length, consumedRanges)) continue;

      // Skip '+'/'-' mutations that are inside longer operators already handled (defensive)
      const mutatedSource = source.slice(0, pos) + to + source.slice(pos + from.length);
      mutants.push({
        mutatedSource,
        description: `position ${pos}: '${from}' mutated to '${to}'`,
      });
    }
    // mark these positions consumed so shorter/overlapping operators don't double-mutate the same spot
    for (const pos of positions) {
      consumedRanges.push([pos, pos + from.length]);
    }
  }

  return mutants;
}

function evaluateFunctionSource(source: string): (...args: unknown[]) => unknown {
  // Wrap and return the declared function via an IIFE
  const factory = new Function(`${source}\nreturn arguments[0];`);
  const match = source.match(/function\s+(\w+)/);
  const fnName = match ? match[1] : null;
  if (!fnName) throw new Error('could not locate function name in source');

  const wrapped = new Function(`${source}\nreturn ${fnName};`);
  return wrapped() as (...args: unknown[]) => unknown;
}

function runMutationTesting(
  source: string,
  testCases: TestCase[]
): { mutationScore: number; survivedMutants: Mutant[] } {
  const mutants = generateMutants(source);

  if (mutants.length === 0) {
    return { mutationScore: 1, survivedMutants: [] };
  }

  const survivedMutants: Mutant[] = [];

  for (const mutant of mutants) {
    let survived = true;
    try {
      const mutatedFn = evaluateFunctionSource(mutant.mutatedSource);
      for (const testCase of testCases) {
        let actual: unknown;
        try {
          actual = mutatedFn(...testCase.input);
        } catch {
          survived = false; // runtime error counts as killed
          break;
        }
        if (actual !== testCase.expectedOutput) {
          survived = false;
          break;
        }
      }
    } catch {
      survived = false; // failed to even compile/evaluate: treat as killed
    }

    if (survived) {
      survivedMutants.push(mutant);
    }
  }

  const killed = mutants.length - survivedMutants.length;
  const mutationScore = killed / mutants.length;

  return { mutationScore, survivedMutants };
}

describe('mutation testing engine', () => {
  test('detects a survived mutant for a weak test suite', () => {
    const source = 'function isEligible(age) { return age >= 18; }';
    const testCases: TestCase[] = [
      { input: [20], expectedOutput: true },
      { input: [10], expectedOutput: false },
    ];

    const result = runMutationTesting(source, testCases);
    expect(result.survivedMutants.some((m) => m.description.includes("'>=' mutated to '>'"))).toBe(
      true
    );
  });

  test('a strengthened test suite kills the boundary mutant', () => {
    const source = 'function isEligible(age) { return age >= 18; }';
    const testCases: TestCase[] = [
      { input: [20], expectedOutput: true },
      { input: [10], expectedOutput: false },
      { input: [18], expectedOutput: true }, // boundary case added
    ];

    const result = runMutationTesting(source, testCases);
    expect(result.survivedMutants.some((m) => m.description.includes("'>=' mutated to '>'"))).toBe(
      false
    );
    expect(result.mutationScore).toBe(1);
  });

  test('source with no mutable operators returns empty mutants and score 1', () => {
    const source = 'function identity(x) { return x; }';
    const result = runMutationTesting(source, [{ input: [5], expectedOutput: 5 }]);
    expect(result.survivedMutants).toEqual([]);
    expect(result.mutationScore).toBe(1);
  });
});

description.en:
Your team wants visual regression testing for a component library, comparing screenshots of rendered components against committed baseline images. Naive pixel-for-pixel comparison is too strict — anti-aliasing differences between CI runs and tiny font-rendering variance cause false positives on every run. Build a diffing utility that compares two same-sized images (represented as flat RGBA byte arrays) and decides pass/fail with a tunable tolerance, plus produces a visual diff overlay.

**Requirements:**

- Implement pixel-by-pixel comparison between a baseline and a candidate image (same width/height, RGBA `Uint8ClampedArray`-like number arrays)
- Support a per-pixel color-distance threshold (small RGB differences within threshold don't count as a mismatch — this absorbs anti-aliasing noise) AND an overall mismatch-percentage threshold (e.g. fail only if more than 0.1% of pixels differ beyond the per-pixel threshold)
- Generate a diff image highlighting mismatched pixels (e.g. paint them a distinct color like solid red) while keeping matched regions faithful to the baseline (or dimmed, your choice — document it) so a human reviewer can see WHERE the regression is
- Images of different dimensions should fail fast with a clear reason, not attempt a pixel comparison

**Function signature:**

```typescript
interface ImageData2 {
  width: number;
  height: number;
  data: number[]; // flat RGBA, length = width * height * 4
}

interface DiffOptions {
  pixelColorThreshold?: number; // default 32 (0-255 scale, euclidean-ish RGB distance)
  maxMismatchPercentage?: number; // default 0.1 (percent, i.e. 0.1 = 0.1%)
}

interface DiffResult {
  passed: boolean;
  mismatchedPixelCount: number;
  mismatchPercentage: number;
  diffImage: ImageData2;
  reason?: string;
}

function compareImages(baseline: ImageData2, candidate: ImageData2, options?: DiffOptions): DiffResult;
```

**Example:**

- Identical images → `passed: true`, `mismatchedPixelCount: 0`
- Images differing by 1 pixel that's fully opposite color (black vs white) out of 10,000 pixels, default 0.1% threshold → 1/10000 = 0.01% < 0.1% → `passed: true` (below the percentage threshold) but `mismatchedPixelCount` still correctly reports `1`
- Same scenario but with `maxMismatchPercentage: 0.005` → `passed: false`

**Edge cases:**

- Different width/height between baseline and candidate → `passed: false`, `reason: 'dimension mismatch'`, no diff image pixel comparison attempted (but still return a valid `diffImage` shape, e.g. same as candidate, or empty — document your choice)
- All pixels within color threshold but exactly at the boundary value → should NOT count as mismatch (threshold is inclusive of 'close enough')
- Fully transparent pixels (alpha = 0) with different RGB values underneath → decide and document whether alpha is factored into the distance calculation

description.ru:
Команда хочет visual regression тестирование для библиотеки компонентов — сравнение скриншотов отрендеренных компонентов с закоммиченными baseline-изображениями. Наивное попиксельное сравнение слишком строгое — различия anti-aliasing между прогонами CI и крошечные вариации рендеринга шрифтов вызывают ложные срабатывания на каждом прогоне. Построй утилиту diff'а, которая сравнивает два изображения одинакового размера (представленные как плоские массивы байтов RGBA) и решает pass/fail с настраиваемым допуском, а также генерирует визуальный diff-оверлей.

**Требования:**

- Реализуй попиксельное сравнение между baseline и candidate изображением (одинаковые ширина/высота, RGBA массивы чисел вроде `Uint8ClampedArray`)
- Поддержи порог цветовой дистанции на пиксель (небольшие различия RGB в пределах порога не считаются несовпадением — это поглощает шум anti-aliasing) И порог общего процента несовпадений (например, фейлить только если более 0.1% пикселей отличаются сверх порога на пиксель)
- Сгенерируй diff-изображение, подсвечивающее несовпадающие пиксели (например, красным сплошным цветом), сохраняя совпадающие области верными baseline (или затемнёнными — твой выбор, задокументируй его), чтобы человек-ревьюер увидел, ГДЕ регрессия
- Изображения разных размеров должны фейлиться быстро с понятной причиной, не пытаясь делать попиксельное сравнение

**Сигнатура функции:**

```typescript
interface ImageData2 {
  width: number;
  height: number;
  data: number[]; // плоский RGBA, длина = width * height * 4
}

interface DiffOptions {
  pixelColorThreshold?: number; // по умолчанию 32 (шкала 0-255, евклидова-подобная дистанция RGB)
  maxMismatchPercentage?: number; // по умолчанию 0.1 (в процентах, т.е. 0.1 = 0.1%)
}

interface DiffResult {
  passed: boolean;
  mismatchedPixelCount: number;
  mismatchPercentage: number;
  diffImage: ImageData2;
  reason?: string;
}

function compareImages(baseline: ImageData2, candidate: ImageData2, options?: DiffOptions): DiffResult;
```

**Пример:**

- Идентичные изображения → `passed: true`, `mismatchedPixelCount: 0`
- Изображения отличаются 1 пикселем, полностью противоположным цветом (чёрный против белого) из 10000 пикселей, дефолтный порог 0.1% → 1/10000 = 0.01% < 0.1% → `passed: true` (ниже порога процента), но `mismatchedPixelCount` всё равно корректно показывает `1`
- Тот же сценарий, но с `maxMismatchPercentage: 0.005` → `passed: false`

**Граничные случаи:**

- Разная ширина/высота между baseline и candidate → `passed: false`, `reason: 'dimension mismatch'`, попиксельное сравнение diff-изображения не выполняется (но всё равно верни валидную форму `diffImage`, например такую же как candidate, или пустую — задокументируй выбор)
- Все пиксели в пределах порога цвета, но ровно на граничном значении → НЕ должно считаться несовпадением (порог включает «достаточно близко»)
- Полностью прозрачные пиксели (alpha = 0) с разными RGB значениями под ними → реши и задокументируй, учитывается ли alpha в расчёте дистанции

