type PropRequirement = 'required' | 'optional';

function validateRemoteContract(
  expectedProps: Record<string, PropRequirement>,
  actualProps: Record<string, unknown>
): { valid: boolean; missingRequired: string[]; unknownExtra: string[] } {
  const missingRequired: string[] = [];
  const unknownExtra: string[] = [];

  for (const [propName, requirement] of Object.entries(expectedProps)) {
    if (requirement === 'required' && !(propName in actualProps)) {
      missingRequired.push(propName);
    }
  }

  for (const propName of Object.keys(actualProps)) {
    if (!(propName in expectedProps)) {
      unknownExtra.push(propName);
    }
  }

  return {
    valid: missingRequired.length === 0,
    missingRequired,
    unknownExtra,
  };
}

interface SemVer {
  major: number;
  minor: number;
  patch: number;
}

function parseVersion(version: string): SemVer | null {
  const match = version.match(/^(\d+)\.(\d+)\.(\d+)/);
  if (!match) return null;
  return { major: Number(match[1]), minor: Number(match[2]), patch: Number(match[3]) };
}

function parseCaretRange(range: string): SemVer | null {
  const stripped = range.startsWith('^') ? range.slice(1) : range;
  return parseVersion(stripped);
}

function compareSemVer(a: SemVer, b: SemVer): number {
  if (a.major !== b.major) return a.major - b.major;
  if (a.minor !== b.minor) return a.minor - b.minor;
  return a.patch - b.patch;
}

function satisfiesCaretRange(version: string, range: string): boolean {
  const parsedVersion = parseVersion(version);
  const rangeBase = parseCaretRange(range);
  if (!parsedVersion || !rangeBase) return false;

  const isAtLeastBase = compareSemVer(parsedVersion, rangeBase) >= 0;
  const isBelowNextMajor = parsedVersion.major < rangeBase.major + 1;

  return isAtLeastBase && isBelowNextMajor;
}

function checkSharedDependencyCompatibility(
  hostVersions: Record<string, string>,
  remoteRequiredRanges: Record<string, string>
): { compatible: boolean; incompatibleDeps: { dep: string; hostVersion: string; requiredRange: string }[] } {
  const incompatibleDeps: { dep: string; hostVersion: string; requiredRange: string }[] = [];

  for (const [dep, requiredRange] of Object.entries(remoteRequiredRanges)) {
    const hostVersion = hostVersions[dep];
    if (!hostVersion || !satisfiesCaretRange(hostVersion, requiredRange)) {
      incompatibleDeps.push({ dep, hostVersion: hostVersion ?? '(not shared)', requiredRange });
    }
  }

  return { compatible: incompatibleDeps.length === 0, incompatibleDeps };
}

// --- Simulated remote loader + host fallback ---
async function loadRemoteComponent(shouldFail: boolean): Promise<{ render: () => string }> {
  if (shouldFail) {
    throw new Error('Failed to fetch remote entry: network error');
  }
  return { render: () => 'remote content' };
}

async function renderHostWithRemote(shouldFail: boolean): Promise<string> {
  try {
    const remote = await loadRemoteComponent(shouldFail);
    return remote.render();
  } catch {
    return 'FALLBACK_UI: product unavailable, please try again later';
  }
}

describe('Module Federation integration harness', () => {
  test('validateRemoteContract flags missing required prop', () => {
    const expectedProps: Record<string, PropRequirement> = {
      productId: 'required',
      onAddToCart: 'required',
      theme: 'optional',
    };
    const actualProps = { productId: '1' };

    const result = validateRemoteContract(expectedProps, actualProps);
    expect(result.valid).toBe(false);
    expect(result.missingRequired).toEqual(['onAddToCart']);
  });

  test('validateRemoteContract flags unknown extra prop', () => {
    const expectedProps: Record<string, PropRequirement> = { productId: 'required' };
    const actualProps = { productId: '1', legacyPropNoLongerUsed: true };

    const result = validateRemoteContract(expectedProps, actualProps);
    expect(result.unknownExtra).toEqual(['legacyPropNoLongerUsed']);
  });

  test('checkSharedDependencyCompatibility flags incompatible React versions', () => {
    const hostVersions = { react: '17.0.2', 'react-dom': '17.0.2' };
    const remoteRequiredRanges = { react: '^18.0.0' };

    const result = checkSharedDependencyCompatibility(hostVersions, remoteRequiredRanges);
    expect(result.compatible).toBe(false);
    expect(result.incompatibleDeps).toEqual([
      { dep: 'react', hostVersion: '17.0.2', requiredRange: '^18.0.0' },
    ]);
  });

  test('checkSharedDependencyCompatibility passes for compatible versions', () => {
    const hostVersions = { react: '18.5.3' };
    const remoteRequiredRanges = { react: '^18.0.0' };

    const result = checkSharedDependencyCompatibility(hostVersions, remoteRequiredRanges);
    expect(result.compatible).toBe(true);
  });

  test('host renders fallback UI when remote fails to load', async () => {
    const output = await renderHostWithRemote(true);
    expect(output).toContain('FALLBACK_UI');
  });

  test('host renders remote content when load succeeds', async () => {
    const output = await renderHostWithRemote(false);
    expect(output).toBe('remote content');
  });
});

