import { Transform, TransformCallback, Writable, Readable } from 'stream';

class ChunkUppercaseTransform extends Transform {
  _transform(chunk: Buffer, encoding: BufferEncoding, callback: TransformCallback): void {
    // Simulate real processing work with an async tick, so that calling callback
    // too early (synchronously) would be observably different from calling it
    // after this delay in tests.
    setImmediate(() => {
      try {
        const result = Buffer.from(chunk.toString().toUpperCase());
        callback(null, result);
      } catch (err) {
        callback(err as Error);
      }
    });
  }
}

class ThrottledWritable extends Writable {
  writesReceived: Buffer[] = [];
  private shouldAcceptWrite: () => boolean;
  private pendingCallbacks: (() => void)[] = [];

  constructor(shouldAcceptWrite: () => boolean, options?: ConstructorParameters<typeof Writable>[0]) {
    super(options);
    this.shouldAcceptWrite = shouldAcceptWrite;
  }

  _write(chunk: Buffer, encoding: BufferEncoding, callback: (error?: Error | null) => void): void {
    this.writesReceived.push(chunk);
    if (this.shouldAcceptWrite()) {
      callback();
    } else {
      // Simulate a slow destination: hold the callback until manually released
      this.pendingCallbacks.push(callback);
    }
  }

  releasePendingWrites(): void {
    const callbacks = this.pendingCallbacks;
    this.pendingCallbacks = [];
    for (const cb of callbacks) cb();
  }
}

describe('ChunkUppercaseTransform backpressure', () => {
  test('callback fires only after processing completes, not synchronously', (done) => {
    const transform = new ChunkUppercaseTransform();
    let callbackFiredSynchronously = true;

    transform._transform(Buffer.from('abc'), 'utf8', () => {
      // If this runs on the same synchronous tick as the call below, that would
      // indicate a broken (non-backpressure-respecting) implementation.
      expect(callbackFiredSynchronously).toBe(false);
      done();
    });

    callbackFiredSynchronously = false; // flips to false once the synchronous call stack unwinds
  });

  test('output chunks are correctly uppercased end to end', (done) => {
    const transform = new ChunkUppercaseTransform();
    const source = Readable.from(['abc', 'def']);
    const collected: string[] = [];

    source
      .pipe(transform)
      .on('data', (chunk: Buffer) => collected.push(chunk.toString()))
      .on('end', () => {
        expect(collected).toEqual(['ABC', 'DEF']);
        done();
      });
  });

  test('slow consumer causes source to pause until drain, buffering stays bounded', (done) => {
    let accepting = false;
    const throttled = new ThrottledWritable(() => accepting, { highWaterMark: 2 });
    const transform = new ChunkUppercaseTransform();

    const chunks = Array.from({ length: 20 }, (_, i) => `chunk-${i}`);
    const source = Readable.from(chunks);

    let maxBuffered = 0;
    const trackBuffered = () => {
      maxBuffered = Math.max(maxBuffered, throttled.writesReceived.length - 0);
    };

    source.pipe(transform).pipe(throttled);

    transform.on('data', trackBuffered);

    // Let a couple of writes go through, then simulate the destination becoming slow.
    setTimeout(() => {
      accepting = false;
      // After some time, release pending writes gradually rather than all at once.
      setTimeout(() => {
        accepting = true;
        throttled.releasePendingWrites();

        throttled.on('finish', () => {
          // With a small highWaterMark, buffered writes-in-flight stays small,
          // proving backpressure limited how much accumulated rather than
          // all 20 chunks queuing up in memory at once.
          expect(maxBuffered).toBeLessThan(chunks.length);
          done();
        });
      }, 50);
    }, 10);
  }, 10000);

  test('error thrown inside _transform propagates as stream error event', (done) => {
    class ThrowingTransform extends Transform {
      _transform(chunk: Buffer, encoding: BufferEncoding, callback: TransformCallback): void {
        setImmediate(() => {
          callback(new Error('processing failed'));
        });
      }
    }

    const source = Readable.from(['will-fail']);
    const transform = new ThrowingTransform();

    source
      .pipe(transform)
      .on('error', (err: Error) => {
        expect(err.message).toBe('processing failed');
        done();
      })
      .on('finish', () => {
        done(new Error('should not reach finish when an error occurred'));
      });
  });

  test('empty input stream completes without ever calling _transform', (done) => {
    let transformCallCount = 0;
    class CountingTransform extends Transform {
      _transform(chunk: Buffer, encoding: BufferEncoding, callback: TransformCallback): void {
        transformCallCount += 1;
        callback(null, chunk);
      }
    }

    const source = Readable.from([]);
    const transform = new CountingTransform();

    source.pipe(transform).on('end', () => {
      expect(transformCallCount).toBe(0);
      done();
    });
  });
});

description.en:
Your team's `UserRepository` has 100% passing unit tests using a mocked PostgreSQL client, yet a production incident happened because a raw SQL query had a subtle bug (a `WHERE` clause that didn't handle NULL correctly) that no mock could ever catch — mocks only verify that your code calls the client with the arguments you expect, not that the actual SQL is correct against a real engine. Design an integration test suite that runs the repository against a real, ephemeral PostgreSQL instance (conceptually via Testcontainers-style dynamic container provisioning — you may simulate the container lifecycle with an in-memory fake DB engine for this exercise, but the test harness and isolation strategy must be real).

**Requirements:**

- Write a `DatabaseTestHarness` that provisions an isolated database state before the full test suite runs (`beforeAll`) and tears it down after (`afterAll`) — simulate 'spinning up a container' as an async setup step with a returned connection object
- Ensure each individual test gets a clean, known data state — use transaction rollback per test (`beforeEach` starts a transaction, `afterEach` rolls it back) rather than re-seeding the whole database per test, and explain why this is dramatically faster for a large test suite
- Write the actual repository method under test — `findActiveUsersByRole(role: string)` — using a raw query pattern, including the exact NULL-handling bug scenario (a role column that can be NULL, and a naive `column = value` comparison that would silently exclude or wrongly include NULL rows depending on the bug direction) — write tests that would have caught this specific bug
- Demonstrate that two tests modifying overlapping data (e.g., both insert a user with the same email) don't interfere with each other, proving the per-test isolation actually works

**Function signature:**

```typescript
interface DbConnection {
  query<T>(sql: string, params: unknown[]): Promise<T[]>;
  begin(): Promise<void>;
  rollback(): Promise<void>;
  commit(): Promise<void>;
}

class DatabaseTestHarness {
  static async start(): Promise<DatabaseTestHarness>;
  getConnection(): DbConnection;
  async stop(): Promise<void>;
}

class UserRepository {
  constructor(private db: DbConnection);
  async findActiveUsersByRole(role: string | null): Promise<{ id: string; email: string; role: string | null }[]>;
}
```

**Example:**

- Seed users: `{ email: 'a@x.com', role: 'admin', active: true }`, `{ email: 'b@x.com', role: null, active: true }`
- `findActiveUsersByRole('admin')` → returns only the admin user
- `findActiveUsersByRole(null)` (looking for users with unset role) → naive SQL `WHERE role = $1` with `params = [null]` would incorrectly return ZERO rows (SQL NULL never equals NULL) — the correct implementation must use `IS NULL` when the parameter is null

**Edge cases:**

- Role value that exists in the table but for an `active: false` user → must not appear in results
- Querying for a role with zero matching users → returns empty array, not an error
- Two tests in sequence both insert `email: 'dup@x.com'` inside their own transaction → the second test must not see or conflict with the first test's row

