interface DbConnection {
  query<T>(sql: string, params: unknown[]): Promise<T[]>;
  begin(): Promise<void>;
  rollback(): Promise<void>;
  commit(): Promise<void>;
}

interface UserRow {
  id: string;
  email: string;
  role: string | null;
  active: boolean;
}

// In-memory fake standing in for a real Testcontainers-provisioned Postgres instance.
// Implements real SQL NULL semantics for the subset of behavior this exercise needs,
// so the same bug that a real engine would expose is reproducible here.
class FakeSqlEngine implements DbConnection {
  private committedRows: UserRow[] = [];
  private transactionRows: UserRow[] | null = null;
  private nextId = 1;

  private get activeRows(): UserRow[] {
    return this.transactionRows ?? this.committedRows;
  }

  async begin(): Promise<void> {
    // snapshot committed state into a working copy; mutations during the
    // transaction only affect this copy until commit
    this.transactionRows = [...this.committedRows];
  }

  async rollback(): Promise<void> {
    this.transactionRows = null; // discard the working copy entirely
  }

  async commit(): Promise<void> {
    if (this.transactionRows) {
      this.committedRows = this.transactionRows;
      this.transactionRows = null;
    }
  }

  async query<T>(sql: string, params: unknown[]): Promise<T[]> {
    if (sql.startsWith('INSERT')) {
      const [email, role, active] = params as [string, string | null, boolean];
      const row: UserRow = { id: String(this.nextId++), email, role, active };
      this.activeRows.push(row);
      return [row] as unknown as T[];
    }

    if (sql.includes('IS NULL')) {
      const [active] = params as [boolean];
      return this.activeRows.filter((r) => r.role === null && r.active === active) as unknown as T[];
    }

    if (sql.includes('role = $1')) {
      const [role, active] = params as [string, boolean];
      // Faithfully reproduces real SQL: '=' comparison against NULL never matches,
      // even if role happens to equal null at the JS level, mirroring Postgres semantics.
      return this.activeRows.filter((r) => r.role !== null && r.role === role && r.active === active) as unknown as T[];
    }

    return [] as unknown as T[];
  }
}

class DatabaseTestHarness {
  private engine: FakeSqlEngine;

  private constructor(engine: FakeSqlEngine) {
    this.engine = engine;
  }

  static async start(): Promise<DatabaseTestHarness> {
    // Simulates the async container-provisioning step (image pull, port binding,
    // readiness poll) that a real Testcontainers setup would perform here.
    await new Promise((resolve) => setTimeout(resolve, 0));
    return new DatabaseTestHarness(new FakeSqlEngine());
  }

  getConnection(): DbConnection {
    return this.engine;
  }

  async stop(): Promise<void> {
    // Simulates container teardown.
  }
}

class UserRepository {
  constructor(private db: DbConnection) {}

  async findActiveUsersByRole(role: string | null): Promise<UserRow[]> {
    if (role === null) {
      // Correct NULL handling: 'IS NULL', not '= NULL'
      return this.db.query<UserRow>('SELECT * FROM users WHERE role IS NULL AND active = $1', [true]);
    }
    return this.db.query<UserRow>('SELECT * FROM users WHERE role = $1 AND active = $2', [role, true]);
  }
}

describe('UserRepository integration (real DB semantics)', () => {
  let harness: DatabaseTestHarness;
  let db: DbConnection;
  let repo: UserRepository;

  beforeAll(async () => {
    harness = await DatabaseTestHarness.start();
    db = harness.getConnection();
    repo = new UserRepository(db);
  });

  afterAll(async () => {
    await harness.stop();
  });

  beforeEach(async () => {
    await db.begin();
  });

  afterEach(async () => {
    // Rollback per test is dramatically cheaper than re-seeding the whole DB:
    // it's an O(1) discard of the transaction's working copy rather than
    // O(n) delete-and-reinsert of every seed row for every single test.
    await db.rollback();
  });

  test('returns only active users matching a non-null role', async () => {
    await db.query('INSERT INTO users (email, role, active) VALUES ($1, $2, $3)', ['a@x.com', 'admin', true]);
    await db.query('INSERT INTO users (email, role, active) VALUES ($1, $2, $3)', ['b@x.com', 'admin', false]);

    const results = await repo.findActiveUsersByRole('admin');
    expect(results).toHaveLength(1);
    expect(results[0].email).toBe('a@x.com');
  });

  test('correctly handles NULL role lookup (catches the production bug)', async () => {
    await db.query('INSERT INTO users (email, role, active) VALUES ($1, $2, $3)', ['b@x.com', null, true]);

    const results = await repo.findActiveUsersByRole(null);
    expect(results).toHaveLength(1);
    expect(results[0].email).toBe('b@x.com');
  });

  test('role with zero matching users returns empty array, not an error', async () => {
    await db.query('INSERT INTO users (email, role, active) VALUES ($1, $2, $3)', ['a@x.com', 'admin', true]);

    const results = await repo.findActiveUsersByRole('nonexistent-role');
    expect(results).toEqual([]);
  });

  test('duplicate email across two sequential tests does not conflict (isolation proof, test 1)', async () => {
    await db.query('INSERT INTO users (email, role, active) VALUES ($1, $2, $3)', ['dup@x.com', 'member', true]);
    const results = await repo.findActiveUsersByRole('member');
    expect(results).toHaveLength(1);
  });

  test('duplicate email across two sequential tests does not conflict (isolation proof, test 2)', async () => {
    // If the rollback in the previous test's afterEach hadn't worked, this insert
    // would collide with or duplicate the previous test's row.
    await db.query('INSERT INTO users (email, role, active) VALUES ($1, $2, $3)', ['dup@x.com', 'member', true]);
    const results = await repo.findActiveUsersByRole('member');
    expect(results).toHaveLength(1); // still just this test's own row, not 2
  });
});

description.en:
Your CI suite has 500 test files and takes 25 minutes on a single runner. You want to split it across N parallel CI workers to cut wall-clock time, but a naive round-robin split by file order causes wildly uneven shard durations (some shards finish in 2 minutes, others take 15) because test files vary enormously in runtime. You also want automatic retry for known-flaky tests WITHOUT masking genuinely broken tests as 'just flaky.'

**Requirements:**

- Write a `assignTestsToShards` function that takes a list of test files with their historical durations (from a previous CI run) and a shard count N, and distributes files across shards to MINIMIZE the difference between the longest and shortest shard's total duration (this is a bin-packing / partition problem — an exact optimal solution isn't required, but your greedy/heuristic approach should be clearly better than round-robin on skewed input)
- Write a `shouldRetryTest` function implementing a bounded, tracked retry policy: a test tagged as "known-flaky" gets up to 2 automatic retries on failure, but the retry must be logged/reported separately from a first-attempt pass so flaky-but-passing-on-retry tests remain VISIBLE in CI reports (not silently hidden as if they passed cleanly) — the goal is retry-with-transparency, not retry-to-hide-problems
- A test NOT tagged as known-flaky should NEVER be auto-retried, even if it fails — auto-retrying arbitrary failures is exactly the anti-pattern that hides real regressions
- Track and expose a per-test flake rate over the last M runs, and flag any test whose flake rate crosses a threshold (e.g., failed on retry-then-passed more than 20% of the last 20 runs) as a candidate for the team to actually fix or quarantine, rather than leaving it silently auto-retried forever

**Function signature:**

```typescript
interface TestFileInfo {
  path: string;
  historicalDurationMs: number;
}

function assignTestsToShards(files: TestFileInfo[], shardCount: number): TestFileInfo[][];

interface RetryDecision {
  shouldRetry: boolean;
  reason: string;
}

function shouldRetryTest(
  testName: string,
  isKnownFlaky: boolean,
  attemptNumber: number, // 1 = first attempt
  maxRetries: number
): RetryDecision;

function computeFlakeRate(recentOutcomes: ('passed-first-try' | 'passed-on-retry' | 'failed')[]): number;
```

**Example:**

- 4 files with durations `[10, 10, 10, 1]` (minutes) split into 2 shards → good split: `[10, 1]` and `[10, 10]` (11 vs 20 — still uneven since 3x10 doesn't divide evenly into 2, but better than round-robin's `[10, 10]` and `[10, 1]` which is the same in this case; use a less trivial example to verify: `[8, 5, 5, 4, 3]` into 2 shards → greedy longest-first assignment gives `[8, 4]`=12 and `[5, 5, 3]`=13, much closer than naive order-based split)
- `shouldRetryTest('checkout flow', true, 2, 2)` → `{ shouldRetry: true, reason: 'known-flaky, attempt 2 of 3 allowed' }`
- `shouldRetryTest('checkout flow', false, 2, 2)` → `{ shouldRetry: false, reason: 'not marked as known-flaky, failures are not auto-retried' }`

**Edge cases:**

- `shardCount` greater than number of files → some shards end up empty, function must not throw
- All files have identical duration → any assignment is equally optimal, round-robin is fine here
- `attemptNumber` exceeds `maxRetries + 1` even for a known-flaky test → `shouldRetry: false`, reason should say retries are exhausted, not confuse this with 'not flaky'

description.ru:
У твоего CI-сьюта 500 тестовых файлов, и он занимает 25 минут на одном раннере. Ты хочешь разбить его на N параллельных CI-воркеров, чтобы сократить wall-clock время, но наивное разбиение round-robin по порядку файлов даёт дико неравномерную длительность шардов (некоторые заканчиваются за 2 минуты, другие занимают 15), потому что файлы тестов сильно различаются по времени выполнения. Также нужен автоматический retry для известно-флейковых тестов БЕЗ маскировки реально сломанных тестов под «просто флейк».

**Требования:**

- Напиши функцию `assignTestsToShards`, которая берёт список тестовых файлов с их историческими длительностями (из предыдущего прогона CI) и число шардов N, и распределяет файлы по шардам, чтобы МИНИМИЗИРОВАТЬ разницу между самым длинным и самым коротким шардом по суммарной длительности (это задача bin-packing/разбиения — точное оптимальное решение не требуется, но твой жадный/эвристический подход должен быть явно лучше round-robin на перекошенном входе)
- Напиши функцию `shouldRetryTest`, реализующую ограниченную, отслеживаемую политику retry: тест, помеченный как «known-flaky», получает до 2 автоматических повторов при падении, но повтор должен логироваться/отражаться в отчёте отдельно от прохождения с первой попытки, чтобы флейковые-но-прошедшие-с-retry тесты оставались ВИДИМЫМИ в отчётах CI (не скрывались молча, как будто они прошли чисто) — цель — retry с прозрачностью, а не retry для сокрытия проблем
- Тест, НЕ помеченный как known-flaky, никогда не должен авто-ретраиться, даже если упал — авто-retry произвольных падений это ровно тот антипаттерн, который скрывает реальные регрессии
- Отслеживай и выставляй наружу flake-rate теста за последние M прогонов, и помечай любой тест, чей flake-rate превышает порог (например, упал-на-первой-попытке-но-прошёл-на-retry более чем в 20% последних 20 прогонов) как кандидата на то, чтобы команда реально его починила или закарантинила, а не оставляла молча авто-ретраиться вечно

**Сигнатура функции:**

```typescript
interface TestFileInfo {
  path: string;
  historicalDurationMs: number;
}

function assignTestsToShards(files: TestFileInfo[], shardCount: number): TestFileInfo[][];

interface RetryDecision {
  shouldRetry: boolean;
  reason: string;
}

function shouldRetryTest(
  testName: string,
  isKnownFlaky: boolean,
  attemptNumber: number, // 1 = первая попытка
  maxRetries: number
): RetryDecision;

function computeFlakeRate(recentOutcomes: ('passed-first-try' | 'passed-on-retry' | 'failed')[]): number;
```

**Пример:**

- 4 файла с длительностями `[10, 10, 10, 1]` (минуты), разбить на 2 шарда → хорошее разбиение: `[10, 1]` и `[10, 10]` (11 против 20 — всё ещё неровно, поскольку 3×10 не делится ровно на 2, но лучше показать на менее тривиальном примере: `[8, 5, 5, 4, 3]` на 2 шарда → жадное распределение «сначала самые длинные» даёт `[8, 4]`=12 и `[5, 5, 3]`=13, гораздо ближе, чем наивное разбиение по порядку)
- `shouldRetryTest('checkout flow', true, 2, 2)` → `{ shouldRetry: true, reason: 'known-flaky, attempt 2 of 3 allowed' }`
- `shouldRetryTest('checkout flow', false, 2, 2)` → `{ shouldRetry: false, reason: 'not marked as known-flaky, failures are not auto-retried' }`

**Граничные случаи:**

- `shardCount` больше числа файлов → некоторые шарды остаются пустыми, функция не должна падать
- Все файлы с одинаковой длительностью → любое распределение одинаково оптимально, round-robin тут подходит
- `attemptNumber` превышает `maxRetries + 1` даже для known-flaky теста → `shouldRetry: false`, причина должна говорить об исчерпании retry, не путать это с «не флейковый»

