solution:
interface TestFileInfo {
  path: string;
  historicalDurationMs: number;
}

function assignTestsToShards(files: TestFileInfo[], shardCount: number): TestFileInfo[][] {
  const shards: TestFileInfo[][] = Array.from({ length: Math.max(shardCount, 0) }, () => []);
  if (shardCount <= 0) return shards;

  const shardTotals = new Array(shardCount).fill(0);

  // Longest Processing Time (LPT) heuristic: sort descending, always place the
  // next item into the currently lightest shard. This is a well-known greedy
  // approximation for the partition/bin-packing problem - not optimal in the
  // worst case, but provably within 4/3 of optimal, and vastly better than
  // order-based round-robin on skewed input.
  const sorted = [...files].sort((a, b) => b.historicalDurationMs - a.historicalDurationMs);

  for (const file of sorted) {
    let lightestShardIndex = 0;
    for (let i = 1; i < shardCount; i++) {
      if (shardTotals[i] < shardTotals[lightestShardIndex]) {
        lightestShardIndex = i;
      }
    }
    shards[lightestShardIndex].push(file);
    shardTotals[lightestShardIndex] += file.historicalDurationMs;
  }

  return shards;
}

interface RetryDecision {
  shouldRetry: boolean;
  reason: string;
}

function shouldRetryTest(
  testName: string,
  isKnownFlaky: boolean,
  attemptNumber: number,
  maxRetries: number
): RetryDecision {
  if (!isKnownFlaky) {
    return {
      shouldRetry: false,
      reason: 'not marked as known-flaky, failures are not auto-retried',
    };
  }

  const totalAllowedAttempts = maxRetries + 1;
  if (attemptNumber >= totalAllowedAttempts) {
    return {
      shouldRetry: false,
      reason: `known-flaky, but retries are exhausted (attempt ${attemptNumber} of ${totalAllowedAttempts} allowed)`,
    };
  }

  return {
    shouldRetry: true,
    reason: `known-flaky, attempt ${attemptNumber} of ${totalAllowedAttempts} allowed`,
  };
}

function computeFlakeRate(recentOutcomes: ('passed-first-try' | 'passed-on-retry' | 'failed')[]): number {
  if (recentOutcomes.length === 0) return 0;
  const retryPassCount = recentOutcomes.filter((o) => o === 'passed-on-retry').length;
  return retryPassCount / recentOutcomes.length;
}

describe('CI sharding and flake retry', () => {
  test('greedy assignment beats round-robin on skewed durations', () => {
    const files: TestFileInfo[] = [
      { path: 'a.test.ts', historicalDurationMs: 8000 },
      { path: 'b.test.ts', historicalDurationMs: 5000 },
      { path: 'c.test.ts', historicalDurationMs: 5000 },
      { path: 'd.test.ts', historicalDurationMs: 4000 },
      { path: 'e.test.ts', historicalDurationMs: 3000 },
    ];

    const shards = assignTestsToShards(files, 2);
    const totals = shards.map((shard) => shard.reduce((sum, f) => sum + f.historicalDurationMs, 0));

    // Greedy LPT should produce totals close to each other (12000 vs 13000),
    // versus a naive contiguous split which would give 18000 vs 7000.
    const spread = Math.max(...totals) - Math.min(...totals);
    expect(spread).toBeLessThanOrEqual(1000);
  });

  test('shardCount greater than file count does not throw, leaves empty shards', () => {
    const files: TestFileInfo[] = [{ path: 'only.test.ts', historicalDurationMs: 1000 }];
    const shards = assignTestsToShards(files, 5);
    expect(shards).toHaveLength(5);
    expect(shards.filter((s) => s.length === 0)).toHaveLength(4);
  });

  test('known-flaky test is retried within limit', () => {
    const decision = shouldRetryTest('checkout flow', true, 2, 2);
    expect(decision.shouldRetry).toBe(true);
  });

  test('known-flaky test retries are exhausted beyond maxRetries', () => {
    const decision = shouldRetryTest('checkout flow', true, 3, 2);
    expect(decision.shouldRetry).toBe(false);
    expect(decision.reason).toContain('exhausted');
  });

  test('non-flaky test is never retried regardless of attempt number', () => {
    const decision = shouldRetryTest('checkout flow', false, 2, 2);
    expect(decision.shouldRetry).toBe(false);
    expect(decision.reason).toContain('not marked as known-flaky');
  });

  test('computeFlakeRate reflects proportion of retry-passes, not just failures', () => {
    const outcomes: ('passed-first-try' | 'passed-on-retry' | 'failed')[] = [
      'passed-first-try', 'passed-on-retry', 'passed-first-try', 'passed-on-retry',
      'passed-first-try', 'passed-first-try', 'passed-first-try', 'passed-first-try',
      'passed-first-try', 'passed-first-try',
    ];
    expect(computeFlakeRate(outcomes)).toBeCloseTo(0.2);
  });
});

description.en:
A large React application has a nested error boundary strategy: a top-level `AppErrorBoundary` wraps the whole app (last resort, shows a full-page error), and individual feature sections wrap themselves in a `FeatureErrorBoundary` (shows a small inline error card, keeps the rest of the app usable). A past incident happened because a feature-level boundary was accidentally missing, so one broken widget crashed the ENTIRE app instead of just that widget. Write tests that verify the isolation boundary actually works at each level, and that errors are reported (not silently swallowed) regardless of which level catches them.

**Requirements:**

- Write a test proving that when a component INSIDE a `FeatureErrorBoundary` throws during render, only that feature's inline fallback UI renders — sibling components elsewhere in the tree (in different feature boundaries, or outside any boundary) remain mounted and functional
- Write a test proving that when a component throws OUTSIDE any `FeatureErrorBoundary` (i.e., only the top-level `AppErrorBoundary` can catch it), the full-page fallback renders and it does NOT leave any of the previously-rendered feature sections silently half-broken in the DOM
- Write a test verifying that every caught error (at either boundary level) invokes an `onError` reporting callback with the error and a component-stack, so errors are never silently caught-and-ignored — assert the callback fires with the correct error object even though the boundary's own render output doesn't show a stack trace to the user
- Write a test for the "reset" capability: after an error is caught and the underlying data/condition that caused it changes, clicking a "Try again" button inside the fallback UI should re-attempt rendering the original children (not just remount the fallback again) — verify this using a component that throws conditionally based on a prop it receives

**Function signature:**

```typescript
interface ErrorBoundaryProps {
  onError?: (error: Error, componentStack: string) => void;
  fallback: (reset: () => void) => React.ReactNode;
  children: React.ReactNode;
}

class FeatureErrorBoundary extends React.Component<ErrorBoundaryProps> {}
class AppErrorBoundary extends React.Component<ErrorBoundaryProps> {}
```

**Example:**

- Tree: `<AppErrorBoundary><FeatureErrorBoundary><BrokenWidget /></FeatureErrorBoundary><OtherWidget /></AppErrorBoundary>` — `BrokenWidget` throws → only its `FeatureErrorBoundary` fallback shows; `OtherWidget` still renders normally
- Same tree but `BrokenWidget` is NOT wrapped in any `FeatureErrorBoundary` → `AppErrorBoundary` catches it, entire tree (including `OtherWidget`) is replaced by the full-page fallback

**Edge cases:**

- An error thrown inside an event handler (not during render) is NOT caught by React error boundaries at all (this is a real React limitation, not a bug in the boundary) — a test should demonstrate awareness of this by showing such an error does NOT trigger the boundary's fallback, and must be handled separately (e.g., try/catch in the handler itself)
- Multiple nested `FeatureErrorBoundary` levels (a boundary inside a boundary) — the innermost one that can catch the error should catch it, not the outer one
- Calling "Try again" while the underlying cause of the error is still present → the error re-throws and the same fallback should reappear, not crash the whole reset mechanism itself

description.ru:
В крупном React-приложении используется вложенная стратегия error boundary: верхнеуровневый `AppErrorBoundary` оборачивает всё приложение (последний рубеж, показывает полноэкранную ошибку), а отдельные фичевые секции оборачивают себя в `FeatureErrorBoundary` (показывает маленькую инлайн-карточку ошибки, оставляя остальное приложение работоспособным). Прошлый инцидент случился из-за того, что фичевый boundary случайно отсутствовал, поэтому один сломанный виджет уронил ВСЁ приложение, а не только этот виджет. Напиши тесты, проверяющие, что изоляция реально работает на каждом уровне, и что ошибки репортятся (не проглатываются молча) независимо от того, какой уровень их поймал.

**Требования:**

- Напиши тест, доказывающий, что когда компонент ВНУТРИ `FeatureErrorBoundary` кидает ошибку при рендере, рендерится только инлайн-fallback этой фичи — соседние компоненты в других местах дерева (в других фичевых boundary или вне любого boundary) остаются смонтированными и работоспособными
- Напиши тест, доказывающий, что когда компонент кидает ошибку ВНЕ любого `FeatureErrorBoundary` (т.е. поймать её может только верхнеуровневый `AppErrorBoundary`), рендерится полноэкранный fallback, и он НЕ оставляет ранее отрендеренные фичевые секции молча наполовину сломанными в DOM
- Напиши тест, проверяющий, что каждая пойманная ошибка (на любом уровне boundary) вызывает колбэк репортинга `onError` с ошибкой и component-stack, так что ошибки никогда не проглатываются молча — убедись, что колбэк срабатывает с правильным объектом ошибки, даже если собственный рендер boundary не показывает пользователю stack trace
- Напиши тест для возможности «сброса»: после того как ошибка поймана и изменилось лежащее в основе условие/данные, вызвавшие её, клик по кнопке «Попробовать снова» внутри fallback UI должен заново попытаться отрендерить исходных children (а не просто перемонтировать fallback снова) — проверь это через компонент, который кидает ошибку условно, в зависимости от переданного пропа

**Сигнатура функции:**

```typescript
interface ErrorBoundaryProps {
  onError?: (error: Error, componentStack: string) => void;
  fallback: (reset: () => void) => React.ReactNode;
  children: React.ReactNode;
}

class FeatureErrorBoundary extends React.Component<ErrorBoundaryProps> {}
class AppErrorBoundary extends React.Component<ErrorBoundaryProps> {}
```

**Пример:**

- Дерево: `<AppErrorBoundary><FeatureErrorBoundary><BrokenWidget /></FeatureErrorBoundary><OtherWidget /></AppErrorBoundary>` — `BrokenWidget` кидает ошибку → показывается только fallback его `FeatureErrorBoundary`; `OtherWidget` рендерится как обычно
- То же дерево, но `BrokenWidget` НЕ обёрнут ни в один `FeatureErrorBoundary` → `AppErrorBoundary` ловит её, всё дерево (включая `OtherWidget`) заменяется полноэкранным fallback

**Граничные случаи:**

- Ошибка, брошенная внутри обработчика события (не во время рендера), вообще НЕ ловится React error boundary (это реальное ограничение React, а не баг boundary) — тест должен продемонстрировать понимание этого, показав, что такая ошибка НЕ триггерит fallback boundary, и должна обрабатываться отдельно (например, try/catch в самом обработчике)
- Несколько вложенных уровней `FeatureErrorBoundary` (boundary внутри boundary) — самый внутренний, способный поймать ошибку, должен её поймать, а не внешний
- Вызов «Попробовать снова», пока причина ошибки всё ещё присутствует → ошибка кидается снова, и должен снова появиться тот же fallback, а не упасть сам механизм сброса

